package com.yjiyun.chatflows.manager.artifact;
import com.yjiyun.chatflows.manager.control.RunIds; import java.io.IOException; import java.nio.file.*; import java.util.Optional;
public final class FileTaskArtifactStore implements TaskArtifactStore { private final Path root; public FileTaskArtifactStore(Path root){this.root=root;} public void writeSpec(String runId,String spec)throws IOException{write(runId,"spec.md",spec);} public void writeMeta(String runId,String meta)throws IOException{write(runId,"meta.json",meta);} public String readSpec(String runId)throws IOException{return Files.readString(task(runId).resolve("spec.md"));} public String readResult(String runId)throws IOException{return Files.readString(task(runId).resolve("result.md"));}public Optional<String> readResultIfExists(String runId)throws IOException{Path p=task(runId).resolve("result.md");return Files.isRegularFile(p)?Optional.of(Files.readString(p)):Optional.empty();} private void write(String id,String name,String body)throws IOException{Path p=task(id).resolve(name);Files.createDirectories(p.getParent());Files.writeString(p,body,StandardOpenOption.CREATE,StandardOpenOption.TRUNCATE_EXISTING);} private Path task(String id){return root.resolve("shared/tasks/task-"+RunIds.requireV4(id));}}
